<?php
namespace App\Services\Developer;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class OutboundWebhookService{public function record(string $event,Model $resource,array $payload=[]):int{$count=0;foreach(DB::table('outbound_webhooks')->where('active',true)->get() as $hook){if(!in_array($event,json_decode($hook->events,true)?:[],true))continue;DB::table('outbound_webhook_deliveries')->insert(['public_uuid'=>(string)Str::uuid(),'outbound_webhook_id'=>$hook->id,'event'=>$event,'event_id'=>(string)Str::uuid(),'payload'=>json_encode(array_merge(['event'=>$event,'occurred_at'=>now()->toIso8601String(),'resource'=>['type'=>$resource::class,'id'=>$resource->getRouteKey()]],$payload)),'status'=>'pending','next_attempt_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$count++;}return $count;}}
